<?php
require __DIR__.'/../includes/bootstrap.php';require __DIR__.'/../includes/layout.php';$user=require_role('admin');$error='';$edit=null;
if (isset($_GET['edit'])) { $q=db()->prepare('SELECT *,DATE_FORMAT(salary_month,\'%Y-%m\') AS month FROM salaries WHERE id=?');$q->execute([record_id($_GET['edit'])]);$edit=$q->fetch();if (!$edit) missing(); }
if (post()) {check_csrf();try {
 $action=$_POST['action']??'';
 if ($action==='delete') { $q=db()->prepare('DELETE FROM salaries WHERE id=?');$q->execute([record_id($_POST['id']??'')]);if (!$q->rowCount()) missing();flash('Salary record deleted.');redirect('admin/salary.php'); }
 if ($action!=='save') throw new InvalidArgumentException('Invalid action.');
 $id=empty($_POST['id'])?null:record_id($_POST['id']);$employee=record_id($_POST['employee_id']??'');$month=text_value('month',7);$status=text_value('payment_status',20);
 if (!preg_match('/^(?:19|20|21)\d{2}-(?:0[1-9]|1[0-2])$/D',$month)) throw new InvalidArgumentException('Enter a salary month between 1900 and 2199.');
 if (!in_array($status,['Pending','Paid'],true)) throw new InvalidArgumentException('Choose a valid payment status.');
 $basic=cents('basic');$allowances=cents('allowances');$deductions=cents('deductions');$net=$basic+$allowances-$deductions;
 if ($net<0 || $net>9999999999) throw new InvalidArgumentException('Deductions cannot exceed earnings; net salary must fit the allowed amount range.');
 $q=db()->prepare("SELECT id FROM users WHERE id=? AND role='employee'");$q->execute([$employee]);if (!$q->fetch()) throw new InvalidArgumentException('Choose an existing employee.');
 $args=[$employee,$month.'-01',decimal_amount($basic),decimal_amount($allowances),decimal_amount($deductions),decimal_amount($net),$status];
 if ($id) {
  $q=db()->prepare('SELECT id FROM salaries WHERE id=?');$q->execute([$id]);if (!$q->fetch()) missing();
  $args[]=$id;$q=db()->prepare('UPDATE salaries SET employee_id=?,salary_month=?,basic=?,allowances=?,deductions=?,net_salary=?,payment_status=? WHERE id=?');
 } else $q=db()->prepare('INSERT INTO salaries (employee_id,salary_month,basic,allowances,deductions,net_salary,payment_status) VALUES (?,?,?,?,?,?,?)');
 $q->execute($args);flash($id?'Salary updated.':'Salary created.');redirect('admin/salary.php');
 } catch (InvalidArgumentException $e) { $error=$e->getMessage(); } catch (PDOException $e) { if ($e->getCode()!=='23000') throw $e;$error='A salary record already exists for this employee and month, or the employee no longer exists.'; }$edit=$_POST;
}
$employees=db()->query("SELECT id,employee_code,full_name FROM users WHERE role='employee' ORDER BY full_name")->fetchAll();$search=trim(is_string($_GET['q']??null)?$_GET['q']:'');
$q=db()->prepare("SELECT s.*,u.full_name,u.employee_code,DATE_FORMAT(s.salary_month,'%Y-%m') AS month FROM salaries s JOIN users u ON u.id=s.employee_id WHERE u.full_name LIKE ? OR u.employee_code LIKE ? OR DATE_FORMAT(s.salary_month,'%Y-%m') LIKE ? ORDER BY s.salary_month DESC,s.id DESC");$q->execute(array_fill(0,3,'%'.$search.'%'));$rows=$q->fetchAll();page_start('Salary Management',$user);if ($error) echo '<p class="notice error-notice" role="alert">'.h($error).'</p>';
?><section class="card record-form"><h2 class="card-title"><?=empty($edit['id'])?'Add Salary Record':'Edit Salary Record'?></h2><?php if (!$employees): ?><p>Add an employee before creating salary records.</p><?php else: ?><form method="post" id="salaryForm"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="form-grid"><div class="form-group"><label for="employee_id">Employee</label><select id="employee_id" name="employee_id" class="form-control" required><?php foreach ($employees as $e): ?><option value="<?=(int)$e['id']?>" <?=(string)$e['id']===(string)($edit['employee_id']??'')?'selected':''?>><?=h($e['full_name'].' — '.$e['employee_code'])?></option><?php endforeach; ?></select></div><?php input_field('month','Salary Month',$edit['month']??date('Y-m'),'month');foreach (['basic'=>'Basic Salary (₹)','allowances'=>'Allowances (₹)','deductions'=>'Deductions (₹)'] as $k=>$l) input_field($k,$l,$edit[$k]??'0','number',true,'min="0" max="99999999.99" step="0.01"'); ?><div class="form-group"><label>Net Salary</label><output id="netPreview" class="net-preview"></output></div><div class="form-group"><label for="payment_status">Payment Status</label><select id="payment_status" name="payment_status" class="form-control"><?php foreach (['Pending','Paid'] as $s): ?><option <?=$s===($edit['payment_status']??'Pending')?'selected':''?>><?=h($s)?></option><?php endforeach; ?></select></div></div><div class="actions"><button class="btn btn-primary">Save Salary</button><a class="btn btn-secondary" href="salary.php">Clear / Cancel</a></div></form><?php endif; ?></section><section class="card"><form method="get"><label for="q">Search employee or month</label><div class="actions"><input id="q" name="q" class="form-control" value="<?=h($search)?>"><button class="btn btn-primary">Search</button></div></form><div class="table-container"><table class="table"><thead><tr><th>Employee</th><th>Month</th><th>Basic</th><th>Allowances</th><th>Deductions</th><th>Net Salary</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $s): ?><tr><td><?=h($s['full_name'])?><br><?=h($s['employee_code'])?></td><td><?=h($s['month'])?></td><td><?=money($s['basic'])?></td><td><?=money($s['allowances'])?></td><td><?=money($s['deductions'])?></td><td><strong><?=money($s['net_salary'])?></strong></td><td><?=h($s['payment_status'])?></td><td><div class="actions"><a class="btn btn-primary" href="?edit=<?=(int)$s['id']?>">Edit</a><form method="post" data-confirm="Delete this salary record?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="btn btn-danger">Delete</button></form></div></td></tr><?php endforeach;if (!$rows): ?><tr><td colspan="8">No salary records found.</td></tr><?php endif; ?></tbody></table></div></section><?php page_end();
